1	/**
2	 * T5 — Regression and responsive QA tests
3	 *
4	 * Covers the T5 checklist items not already addressed by earlier test files:
5	 *
6	 *   - FeatureBoardView renders the feature list and FeatureListRow click target
7	 *   - FeatureListRow renders accessible button attributes (for setSelectedFeature flow)
8	 *   - FeatureListRow does NOT render task-detail-related markup
9	 *   - KanbanBoard-level mode switch: TaskBoardView vs FeatureBoardView rendered in context
10	 *   - Feature Mode default filter hides done, shows active lifecycle statuses
11	 *   - Responsive/overflow safety: required Tailwind overflow classes are present in rendered HTML
12	 *   - First-visit default: board mode falls back to "task" when nothing is stored
13	 */
14	
15	import React from "react";
16	import { renderToStaticMarkup } from "react-dom/server";
17	import { beforeEach, describe, expect, it, vi } from "vitest";
18	import type { ParsedFeature } from "../services/yaml-parser";
19	import type {
20	  ActiveFilters,
21	  FeatureActiveFilters,
22	} from "../features/board/types";
23	import {
24	  getDefaultBoardMode,
25	  getDefaultFeatureStatusFilter,
26	  getStoredBoardMode,
27	  saveBoardMode,
28	} from "../features/board/lib/status-filter-store";
29	import {
30	  matchesFeatureModeSearch,
31	  matchesFeatureModeStatusFilter,
32	} from "../features/board/lib/filter";
33	import { FEATURE_STATUS_OPTIONS } from "../features/board/lib/status";
34	import { FeatureListRow } from "../features/board/components/FeatureBoardView/FeatureListRow";
35	
36	// ─── localStorage shim ─────────────────────────────────────────────────────
37	
38	const store: Record<string, string> = {};
39	const mockLS = {
40	  getItem: (key: string) => store[key] ?? null,
41	  setItem: (key: string, value: string) => {
42	    store[key] = value;
43	  },
44	  removeItem: (key: string) => {
45	    delete store[key];
46	  },
47	  clear: () => {
48	    for (const key of Object.keys(store)) delete store[key];
49	  },
50	};
51	
52	// @ts-expect-error test shim
53	global.window = {};
54	// @ts-expect-error test shim
55	global.localStorage = mockLS;
56	
57	beforeEach(() => {
58	  mockLS.clear();
59	});
60	
61	// ─── helpers ───────────────────────────────────────────────────────────────
62	
63	function makeFeature(overrides: Partial<ParsedFeature> = {}): ParsedFeature {
64	  return {
65	    id: "kanban-board-feature",
66	    title: "Feature Kanban Board",
67	    featureStatus: "in_implementation",
68	    tasks: [],
69	    ...overrides,
70	  };
71	}
72	
73	function makeTask(id: string, title: string, status: string) {
74	  return { id, title, status, dependsOn: [] };
75	}
76	
77	// ─── FeatureListRow — accessible click target ─────────────────────────────
78	
79	describe("FeatureListRow — accessible click target for setSelectedFeature flow", () => {
80	  it("renders with role=button so it is keyboard-accessible", () => {
81	    const html = renderToStaticMarkup(
82	      React.createElement(FeatureListRow, {
83	        feature: makeFeature(),
84	        onClick: () => undefined,
85	      }),
86	    );
87	    expect(html).toContain('role="button"');
88	  });
89	
90	  it("renders with tabIndex=0 to be focusable", () => {
91	    const html = renderToStaticMarkup(
92	      React.createElement(FeatureListRow, {
93	        feature: makeFeature(),
94	        onClick: () => undefined,
95	      }),
96	    );
97	    expect(html).toContain('tabindex="0"');
98	  });
99	
100	  it("renders aria-label that references 'Open feature detail'", () => {
101	    const feature = makeFeature({ title: "Auth System" });
102	    const html = renderToStaticMarkup(
103	      React.createElement(FeatureListRow, {
104	        feature,
105	        onClick: () => undefined,
106	      }),
107	    );
108	    expect(html).toContain("Open feature detail for Auth System");
109	  });
110	
111	  it("renders feature id prominently", () => {
112	    const feature = makeFeature({ id: "auth-system", title: "Auth System" });
113	    const html = renderToStaticMarkup(
114	      React.createElement(FeatureListRow, {
115	        feature,
116	        onClick: () => undefined,
117	      }),
118	    );
119	    expect(html).toContain("auth-system");
120	  });
121	
122	  it("renders feature title when distinct from id", () => {
123	    const feature = makeFeature({
124	      id: "auth-system",
125	      title: "Auth System Feature",
126	    });
127	    const html = renderToStaticMarkup(
128	      React.createElement(FeatureListRow, {
129	        feature,
130	        onClick: () => undefined,
131	      }),
132	    );
133	    expect(html).toContain("Auth System Feature");
134	  });
135	
136	  it("does NOT render task-detail-related content (no data-task-id)", () => {
137	    const feature = makeFeature({
138	      tasks: [makeTask("T1", "Setup OAuth", "in_progress")],
139	    });
140	    const html = renderToStaticMarkup(
141	      React.createElement(FeatureListRow, {
142	        feature,
143	        onClick: () => undefined,
144	      }),
145	    );
146	    expect(html).not.toContain("data-task-id");
147	    expect(html).not.toContain("Setup OAuth");
148	  });
149	
150	  it("renders the feature status pill", () => {
151	    const feature = makeFeature({ featureStatus: "in_implementation" });
152	    const html = renderToStaticMarkup(
153	      React.createElement(FeatureListRow, {
154	        feature,
155	        onClick: () => undefined,
156	      }),
157	    );
158	    expect(html).toContain("In Progress");
159	  });
160	
161	  it("renders without crashing for every feature lifecycle status", () => {
162	    const statuses = [
163	      "in_design",
164	      "in_tdd",
165	      "ready_for_implementation",
166	      "in_implementation",
167	      "in_handoff",
168	      "done",
169	      "blocked",
170	      "cancelled",
171	    ];
172	    for (const status of statuses) {
173	      const feature = makeFeature({ featureStatus: status });
174	      expect(() =>
175	        renderToStaticMarkup(
176	          React.createElement(FeatureListRow, {
177	            feature,
178	            onClick: () => undefined,
179	          }),
180	        ),
181	      ).not.toThrow();
182	    }
183	  });
184	});
185	
186	// ─── FeatureBoardView — rendering via context mock ────────────────────────
187	
188	const mockSetSelectedFeature = vi.hoisted(() => vi.fn());
189	const mockSetSelectedTask = vi.hoisted(() => vi.fn());
190	
191	const featureBoardContextRef = vi.hoisted(() => ({
192	  current: null as unknown,
193	}));
194	
195	vi.mock("../features/board/components/KanbanBoard/KanbanBoard.context", () => ({
196	  useBoardContext: () => featureBoardContextRef.current,
197	}));
198	
199	import { FeatureBoardView } from "../features/board/components/FeatureBoardView/FeatureBoardView";
200	
201	function buildFeatureBoardContext(opts: {
202	  features?: ParsedFeature[];
203	  loading?: boolean;
204	  error?: null | { kind: string; message: string };
205	  featureSearchQuery?: string;
206	  featureActiveFilters?: FeatureActiveFilters;
207	}) {
208	  const taskFilters: ActiveFilters = { statuses: [] };
209	  const featureFilters: FeatureActiveFilters = opts.featureActiveFilters ?? {
210	    statuses: getDefaultFeatureStatusFilter(),
211	  };
212	
213	  return {
214	    workspace: {
215	      id: "test-ws",
216	      owner: "test-owner",
217	      repo: "test-repo",
218	      name: "Test Workspace",
219	      isPrivate: false,
220	      connectedAt: "2026-01-01T00:00:00Z",
221	    },
222	    features: opts.features ?? [],
223	    trackedFeatures: [],
224	    loading: opts.loading ?? false,
225	    error: opts.error ?? null,
226	    reload: vi.fn(),
227	    boardMode: "feature" as const,
228	    setBoardMode: vi.fn(),
229	    taskSearchQuery: "",
230	    setTaskSearchQuery: vi.fn(),
231	    taskActiveFilters: taskFilters,
232	    setTaskActiveFilters: vi.fn(),
233	    featureSearchQuery: opts.featureSearchQuery ?? "",
234	    setFeatureSearchQuery: vi.fn(),
235	    featureActiveFilters: featureFilters,
236	    setFeatureActiveFilters: vi.fn(),
237	    searchQuery: "",
238	    setSearchQuery: vi.fn(),
239	    activeFilters: taskFilters,
240	    setActiveFilters: vi.fn(),
241	    expandedFeatureIds: new Set<string>(),
242	    toggleFeature: vi.fn(),
243	    selectedTask: null,
244	    setSelectedTask: mockSetSelectedTask,
245	    selectedFeature: null,
246	    setSelectedFeature: mockSetSelectedFeature,
247	  };
248	}
249	
250	describe("FeatureBoardView — renders feature rows, not task rows", () => {
251	  beforeEach(() => {
252	    mockSetSelectedFeature.mockClear();
253	    mockSetSelectedTask.mockClear();
254	  });
255	
256	  it("renders an accessible list when features exist", () => {
257	    featureBoardContextRef.current = buildFeatureBoardContext({
258	      features: [makeFeature({ id: "feat-a", title: "Feature A" })],
259	      featureActiveFilters: { statuses: ["in_implementation"] },
260	    });
261	
262	    const html = renderToStaticMarkup(React.createElement(FeatureBoardView));
263	    expect(html).toContain('role="list"');
