266	
267	  it("renders the feature lifecycle status header row with canonical columns", () => {
268	    featureBoardContextRef.current = buildFeatureBoardContext({
269	      features: [
270	        makeFeature({ id: "active-feat", featureStatus: "in_implementation" }),
271	        makeFeature({ id: "blocked-feat", featureStatus: "blocked" }),
272	      ],
273	      featureActiveFilters: { statuses: ["in_implementation", "blocked"] },
274	    });
275	
276	    const html = renderToStaticMarkup(React.createElement(FeatureBoardView));
277	    expect(html.match(/data-feature-status-header/g) ?? []).toHaveLength(
278	      FEATURE_STATUS_OPTIONS.length,
279	    );
280	    expect(html).toContain('aria-label="Feature status columns"');
281	    for (const status of FEATURE_STATUS_OPTIONS) {
282	      expect(html).toContain(`data-feature-status-header="${status.key}"`);
283	      expect(html).toContain(status.label.toUpperCase());
284	    }
285	    expect(html).toMatch(
286	      /data-feature-status-count="in_implementation"[^>]*>1/,
287	    );
288	    expect(html).toMatch(/data-feature-status-count="blocked"[^>]*>1/);
289	    expect(html).toMatch(/data-feature-status-count="done"[^>]*>0/);
290	  });
291	
292	  it("renders each visible feature as one table row with one matching status cell", () => {
293	    featureBoardContextRef.current = buildFeatureBoardContext({
294	      features: [
295	        makeFeature({ id: "active-feat", featureStatus: "in_implementation" }),
296	        makeFeature({ id: "blocked-feat", featureStatus: "blocked" }),
297	        makeFeature({ id: "done-feat", featureStatus: "done" }),
298	      ],
299	      featureActiveFilters: { statuses: ["in_implementation", "blocked"] },
