303	    expect(html.match(/data-feature-grid-row/g) ?? []).toHaveLength(2);
304	    expect(html.match(/data-feature-status-cell/g) ?? []).toHaveLength(
305	      2 * FEATURE_STATUS_OPTIONS.length,
306	    );
307	    expect(html).toContain('data-feature-card-status="in_implementation"');
308	    expect(html).toContain('data-feature-card-status="blocked"');
309	    expect(html.match(/data-feature-card-status/g) ?? []).toHaveLength(2);
310	    expect(html).toContain("active-feat");
