59	export function TaskBoardView() {
60	  const {
61	    features,
62	    loading,
63	    error,
64	    taskSearchQuery,
65	    taskActiveFilters,
66	    expandedFeatureIds,
67	    toggleFeature,
68	    setSelectedTask,
69	    backendTaskResults,
70	    taskSearching,
71	    taskSearchError,
72	    openTaskTab,
73	  } = useBoardContext();
74	
75	  // Use backend search results when a search is active; otherwise filter client-side
76	  const visibleFeatures = useMemo<ParsedFeature[]>(() => {
77	    if (backendTaskResults != null) return backendTaskResults;
78	    return features.filter(
79	      (f) =>
80	        matchesTaskModeSearch(f, taskSearchQuery) &&
81	        matchesTaskModeStatusFilter(f, taskActiveFilters.statuses),
82	    );
83	  }, [features, backendTaskResults, taskSearchQuery, taskActiveFilters]);
84	
85	  const columnCounts = useMemo(() => {
86	    const counts: Record<string, number> = {};
87	    for (const col of STATUS_COLUMNS) counts[col.key] = 0;
88	    for (const feature of visibleFeatures) {
89	      for (const task of feature.tasks) {
90	        if (task.status in counts) counts[task.status]++;
91	      }
92	    }
93	    return counts;
94	  }, [visibleFeatures]);
95	
96	  if (loading || taskSearching) {
97	    return (
98	      <div className="flex flex-1 items-center justify-center">
99	        <p className="text-sm text-text-muted">
100	          {taskSearching ? "Searching..." : "Loading board..."}
101	        </p>
102	      </div>
103	    );
104	  }
105	
106	  const activeError = taskSearchError ?? error;
107	  if (activeError) {
108	    if (activeError.kind === "access_denied")
109	      return <AccessDeniedState message={activeError.message} />;
110	    if (activeError.kind === "not_found")
111	      return <NoWorkflowDataState message={activeError.message} />;
112	    if (activeError.kind === "parse_error")
113	      return <ParseErrorState message={activeError.message} />;
114	    return (
115	      <NetworkErrorState
116	        message={activeError.message}
117	        retryable={activeError.retryable}
118	      />
119	    );
120	  }
121	
122	  if (features.length === 0 && backendTaskResults == null) return <EmptyBoardState />;
123	
124	  if (visibleFeatures.length === 0) {
125	    return (
126	      <EmptyState message="No tasks match the current search or filters." />
127	    );
128	  }
129	
130	  return (
131	    <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden">
132	      <div className="w-full">
133	        <div
134	          className="sticky top-0 z-10 flex w-full border-b border-border"
135	          role="row"
136	          aria-label="Status columns"
137	        >
