139	            <TaskColumnHeader
140	              key={col.key}
141	              label={col.label}
142	              color={col.color}
143	              count={columnCounts[col.key] ?? 0}
144	            />
145	          ))}
146	        </div>
147	
148	        <div role="list" aria-label="Features" className="bg-surface">
149	          {visibleFeatures.map((feature) => (
150	            <div key={feature.id} role="listitem">
151	              <FeatureRow
152	                feature={feature}
153	                isExpanded={expandedFeatureIds.has(feature.id)}
154	                onToggle={() => toggleFeature(feature.id)}
155	                onSelectTask={setSelectedTask}
156	                onOpenTaskTab={openTaskTab}
157	              />
158	            </div>
159	          ))}
160	        </div>
161	      </div>
162	    </div>
163	  );
164	}
