27	  setSelectedWorkspaceId,
28	} from "@/services/local-workspace-store";
29	
30	export type TaskTabEntry = {
31	  taskId: string;
32	  taskName: string;
33	  title: string;
34	  featureId?: string;
35	  featureName?: string;
36	};
37	
38	export type FeatureTabEntry = {
39	  featureId: string;
40	  featureName: string;
41	  title: string;
42	};
43	
44	export type WorkspaceSurface = "board" | "task-tab" | "feature-tab";
45	
46	export type WorkspaceContextValue = {
47	  summaries: LocalWorkspaceSummary[];
48	  selectedWorkspaceId: string | null;
49	  activeWorkspace: WorkspaceDetail | null;
50	  loadingWorkspace: boolean;
51	  workspaceError: ApiError | null;
52	  importingWorkspace: boolean;
53	  importError: ApiError | null;
54	  syncingWorkspace: boolean;
55	  syncError: ApiError | null;
56	
57	  selectWorkspace: (workspaceId: string) => void;
58	  importWorkspace: (body: ImportWorkspaceRequest) => Promise<void>;
59	  clearImportError: () => void;
60	  removeLocalSummary: (workspaceId: string) => void;
61	  syncCurrentWorkspace: () => Promise<void>;
62	  clearSyncError: () => void;
63	
64	  activeSurface: WorkspaceSurface;
65	  openTaskTabs: TaskTabEntry[];
66	  activeTaskTabId: string | null;
67	  openTaskTab: (entry: TaskTabEntry) => void;
68	  closeTaskTab: (taskId: string) => void;
69	  activateTaskTab: (taskId: string) => void;
70	  openFeatureTabs: FeatureTabEntry[];
71	  activeFeatureTabId: string | null;
72	  openFeatureTab: (entry: FeatureTabEntry) => void;
73	  closeFeatureTab: (featureId: string) => void;
74	  activateFeatureTab: (featureId: string) => void;
75	  goToBoard: () => void;
76	};
77	
78	const WorkspaceContext = createContext<WorkspaceContextValue | null>(null);
79	
80	export function WorkspaceProvider({ children }: { children: ReactNode }) {
81	  const [summaries, setSummaries] = useState<LocalWorkspaceSummary[]>([]);
82	  const [selectedWorkspaceId, setSelectedWorkspaceIdState] = useState<string | null>(null);
83	  const [activeWorkspace, setActiveWorkspace] = useState<WorkspaceDetail | null>(null);
84	  const [loadingWorkspace, setLoadingWorkspace] = useState(false);
85	  const [workspaceError, setWorkspaceError] = useState<ApiError | null>(null);
86	  const [importingWorkspace, setImportingWorkspace] = useState(false);
87	  const [importError, setImportError] = useState<ApiError | null>(null);
88	  const [syncingWorkspace, setSyncingWorkspace] = useState(false);
89	  const [syncError, setSyncError] = useState<ApiError | null>(null);
90	
91	  const [activeSurface, setActiveSurface] = useState<WorkspaceSurface>("board");
92	  const [openTaskTabs, setOpenTaskTabs] = useState<TaskTabEntry[]>([]);
93	  const [activeTaskTabId, setActiveTaskTabId] = useState<string | null>(null);
94	  const [openFeatureTabs, setOpenFeatureTabs] = useState<FeatureTabEntry[]>([]);
95	  const [activeFeatureTabId, setActiveFeatureTabId] = useState<string | null>(null);
96	
97	  useEffect(() => {
98	    const storedSummaries = getLocalWorkspaceSummaries();
99	    const storedId = getSelectedWorkspaceId();
100	    setSummaries(storedSummaries);
101	
102	    const workspaceId = resolveBootstrapWorkspaceId(storedSummaries, storedId);
103	
104	    if (workspaceId) {
105	      setSelectedWorkspaceIdState(workspaceId);
106	      loadWorkspace(workspaceId);
107	    }
